package smith

import "testing"

// All nine records from John's bestcrypt_fmt_plug.c: three hashes
// (SHA-256, SHA-512, Whirlpool-512) crossed with both modes (XTS and CBC),
// plus two key slots of one real container.
func TestVerifyBestCryptContainer(t *testing.T) {
	cases := []struct{ record, password string }{
		{"$BestCrypt$1$5$3$16384$240$3154116612$128$32$51f7450dccbb1c947dd46138bf0d80d588b6938b02505642dde9e1ea61481485$1$", "openwall"},
		{"$BestCrypt$1$5$3$16384$240$3154116612$10$64$7f36390c85bc5695d49d5d135cb09e00cbf738bb203d0f0a0181805acc15d1cc6f856af0f738c44eead724a854700700a1595b5b30d47242a277b60df6491dde$1$", "openwall"},
		{"$BestCrypt$1$5$3$16384$240$3154116612$129$64$06b513b2ac314636f616747c4171700133c00d335ee6a6c3a8db60bf672531624f099fa90b8047a5aceb2492c5858cab529cf9ba5d7e8c715e33517b64ef4251$1$", "openwall"},
		{"$BestCrypt$1$5$3$16384$240$3154116610$128$32$42ea77745d3430a906f988ce035de539626dd6ef256120cabca0995e3682b89b$1$", "openwall"},
		{"$BestCrypt$1$5$3$16384$240$3154116610$129$64$8ede312199fd2c95c895a70020a257dc8d26b7768e701e0db21b8dbcc5d74817c9e92b96a672b8b5a073f3d78c8cedeec18620dbcf968095f05e4d0c42b2a9ca$1$", "openwall"},
		{"$BestCrypt$1$5$3$16384$240$3154116610$10$64$82157a6df840155fd2bb70681dbf1553e62d7559f8d0fd484364e4681d56c51d2b48f04b1c5a7f7c1b2a2ac20197da5c4d48ff1bd4f0a182364d37af17f43afb$1$", "openwall"},
		{"$BestCrypt$1$5$3$16384$240$3154116610$129$64$65656e4d18c599d592a8ca416fcab3d64de3592733aca7f145020396ca9150827f041b6cd49cea398f26c1794d943cc84b14cf8379a19edce7667a56dade5cec$1$", "password123"},
		{"$BestCrypt$1$5$3$16384$240$3154116612$129$64$c8d1e54303eb356636e138295e49533f250d4c327f57ceae134cb3995a7c01ea8814b0352dd7300899d2adf803c90f7a6872c27234693a8ba2dd354be30dbee5$1$", "password@123"},
		{"$BestCrypt$1$5$3$16384$240$3154116612$129$64$c8d1e54303eb356636e138295e49533f250d4c327f57ceae134cb3995a7c01ea8814b0352dd7300899d2adf803c90f7a6872c27234693a8ba2dd354be30dbee5$1$", "openwall123"},
	}
	for _, c := range cases {
		ok, err := verifyBestCryptContainer(c.record, c.password)
		if err != nil {
			t.Fatalf("verifyBestCryptContainer(%.40s..., %q): %v", c.record, c.password, err)
		}
		if !ok {
			t.Errorf("verifyBestCryptContainer(%.40s..., %q) = false, want true", c.record, c.password)
		}
		if bad, err := verifyBestCryptContainer(c.record, c.password+"x"); err != nil || bad {
			t.Errorf("verifyBestCryptContainer(%.40s..., wrong password) = %v, %v; want false, nil", c.record, bad, err)
		}
	}
}
